            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, k, g) {
            if (this.ROUND_OF[g] <= k) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _get(obj, key, dflt) {
            return Object.prototype.hasOwnProperty.call(obj, key) ? obj[key] : dflt;
        }

        _event(dec, k) {
            var c = this.C;
            var self = this;
            var a = {};
            var j;
            for (j = 0; j < this.KEYS.length; j++) { a[this.KEYS[j]] = this._active(dec, k, this.KEYS[j]); }
            var rc = this.REC[a.receta1], po = this.POS[a.posicion1], di = this.DIS[a.distribucion2], mo = this.MOM[a.momento2];
            var pr = this.PRI[a.precio3], ap = this.APO[a.apoyo3], rs = this.RES[a.respuesta4], fi = this.FID[a.fidelizar4];
            var aware = this._clamp(ap[0] * mo[1] + rs[2], 0.0, 0.95);
            var vis = di[1] * rc[3] * (0.5 + 0.5 * fi[3]);
            var pfit = (a.precio3 === 'premium') ? po[2] : 1.0;
            var x = c.BETA * aware * vis * po[0] * pr[2] * ap[1] * mo[0] * pfit;
            var reachable = di[0] * di[2];
            var trial = reachable * (1.0 - Math.exp(-x));
            var rep = rc[0] * po[1] * pr[3] * ap[2] * mo[2] * rs[0] * fi[0] * di[2];
            if (a.precio3 === 'premium') {
                rep = rep * (1.0 / pr[3]) * ((a.posicion1 !== 'gourmet') ? 0.88 : 1.0) * ((a.posicion1 === 'gourmet') ? pfit : 1.0);
            }
            rep = this._clamp(rep, 0.0, c.RMAX);
            var depth = c.DEPTH + fi[1];
            var trialUnits = c.U * trial;
            var repUnits = c.U * trial * rep * depth * c.YEAR_SHARE * (0.5 + 0.5 * rs[3]);
            var units = trialUnits + repUnits;
            var share = trial * rep * depth * (0.5 + 0.5 * rs[3]) / c.CAT_UNITS;
            var netReg = pr[0] / c.VAT * c.RET * di[4];
            var netLaunch = pr[1] / c.VAT * c.RET * di[4];
            var ucost = c.COST + rc[1];
            var mTrial = trialUnits * (netLaunch - ucost);
            var net2 = netReg * rs[1];
            var mRep1 = repUnits * 0.5 * (netReg - ucost);
            var promoShare = (fi[2] > 0) ? 0.40 : 0.0;
            var mRep2 = repUnits * 0.5 * ((1.0 - promoShare) * (net2 - ucost) + promoShare * (net2 * fi[2] - ucost));
            var coupons = repUnits * 0.5 * c.COUPON * ((a.fidelizar4 === 'cupon') ? 0.35 : 0.0);
            var revenue = trialUnits * netLaunch + repUnits * 0.5 * netReg + repUnits * 0.5 * net2;
            var invest = rc[2] + di[3] + mo[3] + ap[3] + rs[4] + fi[4];
            var contrib = mTrial + mRep1 + mRep2 - coupons - invest;
            var hard = 0;
            this.HARD.forEach(function(h2) { if (a[h2[0]] === h2[1] && k >= self.ROUND_OF[h2[0]]) { hard += 1; } });
            return { k: k, a: a, aware: aware, trial: trial, rep: rep, units: units, share: share, revenue: revenue,
                     invest: invest + coupons, contrib: contrib, hard: hard };
        }

        _components(r) {
            var c = this.C;
            return [this._clamp((r.share - c.S_LO) / (c.S_HI - c.S_LO), 0, 1),
                    this._clamp((r.rep - c.R_LO) / (c.R_HI - c.R_LO), 0, 1),
                    this._clamp((r.contrib - c.M_LO) / (c.M_HI - c.M_LO), 0, 1)];
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._event(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_S, c.W_R, c.W_M];
            var tw = 0, num = 0, i;
            for (i = 0; i < 3; i++) { tw += w[i]; num = num + w[i] * comps[i]; }
            var score = this._clamp(100.0 * num / tw, 0, 100);
            if (m.hard > 0) {
                score = Math.min(score, c.CAP1 - c.CAP_STEP * (m.hard - 1));
            }
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.ROUND_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
            }
            return this._clamp(this._jsround(num / den), 0, 100);
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'es';
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var sep = (this._lang() === 'en') ? ',' : '.';
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = sep + out; }
            }
            return (n < 0 && v > 0 ? '-' : '') + out;
        }

        _fmtDec(n) {
            var v = Math.round(n * 10) / 10;
            var whole = Math.floor(Math.abs(v));
            var dec = Math.round((Math.abs(v) - whole) * 10);
            var s = String(whole) + ((this._lang() === 'en') ? '.' : ',') + String(dec);
            return (v < 0 ? '-' : '') + s;
        }

        _r1(x) {
            return this._jsround(x * 10.0) / 10.0;
        }

        _r2(x) {
            return this._jsround(x * 100.0) / 100.0;
        }

        _fmtDec2(n) {
            var v = Math.round(Math.abs(n) * 100);
            var whole = Math.floor(v / 100);
            var cents = v - whole * 100;
            var cs = (cents < 10 ? '0' : '') + String(cents);
            return (n < 0 && v > 0 ? '-' : '') + String(whole) + ((this._lang() === 'en') ? '.' : ',') + cs;
        }

        _fmtPctS(n) {
            var body = this._fmtDec(n);
            var sign = (n > 0) ? '+' : '';
            return sign + body + ((this._lang() === 'en') ? '%' : ' %');
        }

        _fmtMoney(n) {
            var v = Math.round(n);
            var body = this._fmtInt(Math.abs(v));
            if (this._lang() === 'en') { return (v < 0 ? '-' : '') + '€' + body; }
            return (v < 0 ? '-' : '') + body + ' €';
        }

        _fmtMoney2(n) {
            var body = this._fmtDec2(n);
            if (this._lang() === 'en') { return (n < 0 ? '-' : '') + '€' + body.replace('-', ''); }
            return body + ' €';
        }

        _fmtPct1(n) {
            return this._fmtDec(n) + ((this._lang() === 'en') ? '%' : ' %');
        }

        _fmtPct2(n) {
            return this._fmtDec2(n) + ((this._lang() === 'en') ? '%' : ' %');
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(key) {
                var el = document.getElementById(key);
                if (el && k[key]) { el.value = k[key]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state, forcedPeriod) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = forcedPeriod || state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var cH = ds.cuotaHistory || [];
            var rH = ds.repeticionHistory || [];
            var mH = ds.contribucionHistory || [];
            var pH = ds.pruebaHistory || [];
            var aH = ds.conocimientoHistory || [];
            var n = cH.length;
            this._set('cuotaDisplay', n ? this._fmtPct2(cH[n - 1]) : '-');
            this._set('repeticionDisplay', n ? this._fmtPct1(rH[n - 1]) : '-');
            this._set('contribDisplay', n ? this._fmtMoney(mH[n - 1]) : '-');
            this._set('pruebaDisplay', n ? this._fmtPct1(pH[n - 1]) : '-');
            this._set('conocimientoDisplay', n ? this._fmtPct1(aH[n - 1]) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        _fbKey(g, v) {
            var pfx = { receta1: 're', posicion1: 'po', distribucion2: 'di', momento2: 'mo', precio3: 'pr', apoyo3: 'ap', respuesta4: 'rs', fidelizar4: 'fi' };
            var opts = {
                receta1: ['ajustar', 'actual', 'barata', 'gama'],
                posicion1: ['fresca', 'defensas', 'gourmet', 'precio'],
                distribucion2: ['foco', 'nacional', 'online', 'exclusiva'],
                momento2: ['septiembre', 'julio', 'octubre', 'noviembre'],
                precio3: ['valor', 'penetracion', 'premium', 'tachado'],
                apoyo3: ['muestreo', 'tv', 'promo', 'digital'],
                respuesta4: ['diferenciar', 'igualar', 'tv', 'retirar'],
                fidelizar4: ['cupon', 'sabores', 'dosxuno', 'nada']
            };
            var keys = {
                fb_re_ajustar: 1, fb_re_actual: 1, fb_re_barata: 1, fb_re_gama: 1,
                fb_po_fresca: 1, fb_po_defensas: 1, fb_po_gourmet: 1, fb_po_precio: 1,
                fb_di_foco: 1, fb_di_nacional: 1, fb_di_online: 1, fb_di_exclusiva: 1,
                fb_mo_septiembre: 1, fb_mo_julio: 1, fb_mo_octubre: 1, fb_mo_noviembre: 1,
                fb_pr_valor: 1, fb_pr_penetracion: 1, fb_pr_premium: 1, fb_pr_tachado: 1,
                fb_ap_muestreo: 1, fb_ap_tv: 1, fb_ap_promo: 1, fb_ap_digital: 1,
                fb_rs_diferenciar: 1, fb_rs_igualar: 1, fb_rs_tv: 1, fb_rs_retirar: 1,
                fb_fi_cupon: 1, fb_fi_sabores: 1, fb_fi_dosxuno: 1, fb_fi_nada: 1
            };
            if (!opts[g] || opts[g].indexOf(v) < 0) { return 'fb_next'; }
            var key = 'fb_' + pfx[g] + '_' + v;
            return keys[key] ? key : 'fb_next';
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var m = this._event(this._flat(state, p), p);
            var a = m.a;
            if (m.hard > 0) { return this._t('hint_cap'); }
            var ctl = this.CONTROLS[p] || [];
            var i;
            for (i = 0; i < ctl.length; i++) {
                if (a[ctl[i]] !== this.BEST[ctl[i]]) { return this._t(this._fbKey(ctl[i], a[ctl[i]])); }
            }
            return null;
        }

