        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var mm = Math.max(1, n);
            var d = this._flat(state, mm);
            var m = this._event(d, mm);
            var kp = this._kpis(m);
            var composite = this._composite(state);
            var insights = [];
            var self = this;
            var shown = this.KEYS.filter(function(g) { return self.ROUND_OF[g] <= mm; });
            shown.forEach(function(g) { insights.push(self._t(self._fbKey(g, self._active(d, mm, g)))); });
            if (m.hard > 0) { insights.push(this._t('cm_cap')); }
            insights.push(this._t('fb_next'));
            var vk = this._verdictKey(composite);
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: vk.replace('verdict_', ''),
                performanceLabel: this._t(vk),
                inversion: kp.inversion,
                conocimiento: kp.conocimiento,
                prueba: kp.prueba,
                repeticion: kp.repeticion,
                unidades: kp.unidades,
                ventas: kp.ventas,
                cuota: kp.cuota,
                contribucion: kp.contribucion,
                hard: m.hard,
                periods: (history || []).length,
                insights: insights
            };
        }

