                + '<div class="ej2723-cm-kpi">' + this._t('cm_kpi_repeticion') + ' <strong>' + this._fmtPct1(s.repeticion || 0) + '</strong></div>'
                + '<div class="ej2723-cm-kpi">' + this._t('cm_kpi_contrib') + ' <strong>' + this._fmtMoney(s.contribucion || 0) + '</strong></div>'
                + '<div class="ej2723-cm-kpi">' + this._t('cm_kpi_prueba') + ' <strong>' + this._fmtPct1(s.prueba || 0) + '</strong></div>'
                + '<div class="ej2723-cm-kpi">' + this._t('cm_kpi_conocimiento') + ' <strong>' + this._fmtPct1(s.conocimiento || 0) + '</strong></div>'
                + '<div class="ej2723-cm-kpi">' + this._t('cm_kpi_inversion') + ' <strong>' + this._fmtMoney(s.inversion || 0) + '</strong></div>'
